:7px;color:#7de8dc;background:rgba(89,220,207,.11);font-size:9px}.card-heading p{margin:4px 0 0;color:#6e79a9;font-size:10px}.legend{display:flex;gap:14px;color:#7e89b5;font-size:9px}.legend i{display:inline-block;width:6px;height:6px;margin-left:4px;border-radius:50%}.green-dot{background:#71e1d5}.orange-dot{background:#ffbd73}.table-responsive{overflow-x:auto}.plans-table{width:100%;min-width:1180px;border-collapse:collapse;text-align:right}.plans-table th,.plans-table td{padding:13px 18px;border-top:1px solid rgba(138,152,222,.09);vertical-align:middle}.plans-table th{color:#6874a6;background:rgba(10,16,47,.35);font-size:9px;font-weight:600}.plans-table td{color:#d9ddf5;font-size:10px}.plan-cell{display:flex;align-items:center;gap:9px}.plan-avatar{width:31px;height:31px;display:grid;place-items:center;border-radius:9px;color:#252058;background:linear-gradient(145deg,#80e8df,#ac84fa);font-size:9px;font-weight:800}.plan-cell strong,.plan-cell span{display:block}.plan-cell strong{font-size:10px}.plan-cell span,.people-cell,.muted{color:#7782b0;font-size:9px}.milestone{min-width:145px}.date{display:block;color:#aeb6d7;direction:ltr;text-align:right;font-size:9px}.status-badge{display:inline-flex;align-items:center;gap:5px;margin-top:5px;padding:4px 6px;border-radius:6px;font-size:8px}.status-badge i{width:5px;height:5px;border-radius:50%}.status-badge small{display:block;margin-right:4px;color:#7782b0;font-size:8px}.status-green{color:#78e4d8;background:rgba(90,220,207,.1)}.status-green i{background:#70e1d5}.status-orange{color:#ffc27d;background:rgba(255,185,89,.1)}.status-orange i{background:#ffbd73}.status-red{color:#ff9bad;background:rgba(255,103,139,.1)}.status-red i{background:#ff8fa4}.status-gray{color:#aab5da;background:rgba(133,149,218,.1)}.status-gray i{background:#97a5d0}.confirm-btn{margin-top:5px;padding:5px 7px;border:1px solid rgba(117,231,218,.2);border-radius:6px;color:#78e4d8;background:rgba(90,220,207,.08);font:inherit;font-size:8px;cursor:pointer}.confirm-btn.review{color:#c491ff;border-color:rgba(190,130,255,.22);background:rgba(180,112,255,.08)}.confirm-btn:hover:not(:disabled){filter:brightness(1.3)}.confirm-btn:disabled{opacity:.5;cursor:wait}.details-cell{min-width:160px}.details-cell p{max-width:145px;margin:5px 0;color:#66729f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:8px}.link-btn,.details-btn{display:block;color:#78e5da;text-decoration:none;font-size:9px}.details-btn{padding:4px 7px;border:1px solid rgba(180,112,255,.2);border-radius:6px;color:#c491ff;background:rgba(180,112,255,.08);font:inherit;cursor:pointer}.details-btn:hover{filter:brightness(1.25)}.state-cell{height:145px;color:#7d89b6!important;text-align:center!important}.spinner{display:inline-block;width:15px;height:15px;margin-left:7px;vertical-align:middle;border:2px solid rgba(125,232,220,.25);border-top-color:#7de8dc;border-radius:50%;animation:spin .7s linear infinite}.modal-overlay{position:fixed;inset:82px 0 0;z-index:100;display:grid;place-items:start center;padding:18px;overflow-y:auto;background:rgba(4,7,27,.78);backdrop-filter:blur(7px)}.modal-content{width:min(500px,100%);max-height:calc(100vh - 118px);overflow-y:auto;position:relative;padding:28px;border:1px solid rgba(146,160,233,.2);border-radius:20px;background:linear-gradient(145deg,#171d52,#0d143a);box-shadow:0 25px 70px rgba(0,0,0,.4)}.modal-close{position:absolute;top:12px;left:16px;border:0;color:#8994c2;background:transparent;font-size:25px;cursor:pointer}.modal-icon{width:42px;height:42px;display:grid;place-items:center;margin-bottom:12px;border-radius:12px;color:#202057;background:linear-gradient(145deg,#80e8df,#b486fb);font-size:21px}.modal-content h3{margin:7px 0 2px;font-size:21px}.modal-content>p{margin:0;color:#818cb9;font-size:11px}.details-form{margin-top:23px}.form-group{margin-bottom:16px}.form-group label{display:block;margin-bottom:6px;color:#b8c0e2;font-size:10px}.form-group input,.form-group textarea{width:100%;padding:0 11px;border:1px solid rgba(145,160,230,.2);border-radius:9px;outline:0;color:#eef0ff;background:rgba(6,11,37,.46);font:inherit;font-size:10px}.form-group input{min-height:42px}.form-group textarea{padding-top:10px;resize:vertical}.form-group input:focus,.form-group textarea:focus{border-color:#76e8de;box-shadow:0 0 0 3px rgba(118,232,222,.08)}.form-group input::placeholder,.form-group textarea::placeholder{color:#626e9e}.modal-actions{display:flex;justify-content:flex-start;gap:9px;margin-top:18px}.secondary-btn{min-height:43px;padding:0 18px;border:1px solid rgba(143,157,226,.2);border-radius:10px;color:#aab4dc;background:transparent;font:inherit;font-size:11px;cursor:pointer}.toast-message{position:fixed;left:25px;bottom:25px;z-index:200;padding:12px 17px;border:1px solid rgba(116,232,220,.22);border-radius:10px;color:#bdf7f0;background:#182552;box-shadow:0 12px 30px rgba(0,0,0,.25);font-size:11px}.toast-enter-active,.toast-leave-active{transition:.25s}.toast-enter-from,.toast-leave-to{opacity:0;transform:translateY(10px)}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:720px){.page-topline{align-items:flex-start;flex-direction:column}.page-topline h2{font-size:24px}.assignment-badge{width:100%;justify-content:center}.summary-strip{grid-template-columns:1fr 1fr}.sync-status{grid-column:1/-1}.card-heading{padding-right:15px;padding-left:15px}.legend{display:none}.plans-table th,.plans-table td{padding-right:14px;padding-left:14px}.modal-overlay{inset:70px 0 0;padding:12px}.modal-content{max-height:calc(100vh - 82px);padding:23px 18px}}
</style>